<?php require_once __DIR__.'/_helpers.php';$p=$_GET['province']??'';$d=$_GET['district']??'';$ds=array_values(array_filter(pdata('districts'),fn($x)=>!$p||$x['province_id']===$p));$ss=array_values(array_filter(pdata('sectors'),fn($x)=>!$d||$x['district_id']===$d));?><section><div class="page-heading"><div><span class="eyebrow">Administrative hierarchy</span><h2>Locations</h2><p>Province → District → Sector → Cell → Village.</p></div></div><div class="panel"><form class="form-grid"><label>Province<select name="province" onchange="this.form.submit()"><option value="">All provinces</option><?php foreach(pdata('provinces') as $x):?><option value="<?=$x['id']?>" <?=$p===$x['id']?'selected':''?>><?=htmlspecialchars($x['name'])?></option><?php endforeach;?></select></label><label>District<select name="district" onchange="this.form.submit()"><option value="">All districts</option><?php foreach($ds as $x):?><option value="<?=$x['id']?>" <?=$d===$x['id']?'selected':''?>><?=htmlspecialchars($x['name'])?></option><?php endforeach;?></select></label></form><div class="location-cards"><?php foreach(array_slice($ss,0,12) as $s){$cells=array_filter(pdata('cells'),fn($c)=>$c['sector_id']===$s['id']);$vill=array_filter(pdata('villages'),fn($v)=>in_array($v['cell_id'],array_column($cells,'id'),true));?><div class="location-card"><strong><?=htmlspecialchars($s['name'])?></strong><small><?=count($cells)?> cells · <?=count($vill)?> villages</small></div><?php }?></div></div></section>
